package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for HypergeometricDistribution#getNumericalMean.
 */
public class HypergeometricDistribution_getNumericalMean_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetNumericalMean_StandardCase() {
        // populationSize = 100, numberOfSuccesses = 20, sampleSize = 10
        // Mean = (10 * 20) / 100 = 2.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(100, 20, 10);
        double expected = 2.0;
        assertEquals(expected, distribution.getNumericalMean(), EPSILON);
    }

    @Test
    public void testGetNumericalMean_SmallValues() {
        // populationSize = 10, numberOfSuccesses = 1, sampleSize = 1
        // Mean = (1 * 1) / 10 = 0.1
        HypergeometricDistribution distribution = new HypergeometricDistribution(10, 1, 1);
        double expected = 0.1;
        assertEquals(expected, distribution.getNumericalMean(), EPSILON);
    }

    @Test
    public void testGetNumericalMean_AllSuccesses() {
        // populationSize = 50, numberOfSuccesses = 50, sampleSize = 10
        // Mean = (10 * 50) / 50 = 10.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(50, 50, 10);
        double expected = 10.0;
        assertEquals(expected, distribution.getNumericalMean(), EPSILON);
    }

    @Test
    public void testGetNumericalMean_ZeroSuccesses() {
        // populationSize = 100, numberOfSuccesses = 0, sampleSize = 10
        // Mean = (10 * 0) / 100 = 0.0
        // Note: Depending on implementation constraints, numberOfSuccesses might need to be >= 0.
        // Based on common math libs, 0 is usually allowed.
        HypergeometricDistribution distribution = new HypergeometricDistribution(100, 0, 10);
        double expected = 0.0;
        assertEquals(expected, distribution.getNumericalMean(), EPSILON);
    }

    @Test
    public void testGetNumericalMean_LargeValues() {
        // populationSize = 1000000, numberOfSuccesses = 500000, sampleSize = 500000
        // Mean = (500000 * 500000) / 1000000 = 250000.0
        HypergeometricDistribution distribution = new HypergeometricDistribution(1000000, 500000, 500000);
        double expected = 250000.0;
        assertEquals(expected, distribution.getNumericalMean(), EPSILON);
    }
}
